action:
if((Get-FileHash -LiteralPath $shaderLeasePath).Hash.ToLowerInvariant() -ne $shaderLeaseHash) {throw 'Lease changed before action'}
if([DateTime]::UtcNow -ge $shaderDeadline) {throw 'Grant deadline expired before action'}
$memory=Get-CimInstance Win32_OperatingSystem
if($memory.FreePhysicalMemory * 1KB -lt 8GB) {throw 'Less than 8 GiB available physical memory'}
$shaderLease | ConvertTo-Json -Depth 8 | Set-Content (Join-Path $shaderEvidence 'authorization.json') -Encoding utf8
[ordered]@{sourceLeasePath=$shaderLeasePath;sourceLeaseSha256=$shaderLeaseHash;utc=[DateTime]::UtcNow.ToString('o');deadlineUtc=$shaderDeadline.ToString('o');freeMemoryBytes=$memory.FreePhysicalMemory*1KB;freeDBytes=([IO.DriveInfo]::new('D:\')).AvailableFreeSpace;processTemp=[IO.Path]::GetTempPath();sourceHead=(git -C $shaderRoot rev-parse HEAD)} | ConvertTo-Json | Set-Content (Join-Path $shaderEvidence 'preflight.json') -Encoding utf8
$start=[Diagnostics.ProcessStartInfo]::new()
$start.FileName=Join-Path $shaderRoot 'work\whole-task-20260915\resumed-preparation\validation-env\Scripts\python.exe'
$start.UseShellExecute=$false
$start.CreateNoWindow=$true
$start.RedirectStandardOutput=$true
$start.RedirectStandardError=$true
$start.WorkingDirectory=$shaderRoot
foreach($arg in @('-B',(Join-Path $PSScriptRoot 'prepare_files.py'),$shaderEvidence,([DateTimeOffset]$shaderDeadline).ToUnixTimeSeconds().ToString(),(Get-Process -Id $PID).Path)) {$start.ArgumentList.Add($arg)}
$child=[Diagnostics.Process]::Start($start)
$stdout=$child.StandardOutput.ReadToEndAsync()
$stderr=$child.StandardError.ReadToEndAsync()
$birth=$child.StartTime.ToUniversalTime()
$record=[ordered]@{processId=$child.Id;startedUtc=$birth.ToString('o');executable=$start.FileName;arguments=@($start.ArgumentList);exitCode=$null;stopReason=$null;children=@()}
$peak=0L
try {
    while(-not $child.WaitForExit(3000)) {
        $free=([IO.DriveInfo]::new('D:\')).AvailableFreeSpace
        $freeMemory=(Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory * 1KB
        $bytes=0L
        if(Test-Path -LiteralPath $shaderDestination) {$bytes=[long](Get-ChildItem -LiteralPath $shaderDestination -Recurse -File | Measure-Object Length -Sum).Sum}
        $bytes += [long](Get-ChildItem -LiteralPath $shaderEvidence,$shaderParentTemp -Recurse -File | Measure-Object Length -Sum).Sum
        $peak=[Math]::Max($peak,$bytes)
        [ordered]@{utc=[DateTime]::UtcNow.ToString('o');freeDBytes=$free;freeMemoryBytes=$freeMemory;privateLogicalBytes=$bytes;growthEnvelopeBytes=20GB;peakObservedPrivateLogicalBytes=$peak} | ConvertTo-Json -Compress | Add-Content (Join-Path $shaderEvidence 'resource-samples.jsonl') -Encoding utf8
        $descendants=@(Get-CimInstance Win32_Process | Where-Object ParentProcessId -eq $child.Id | Select-Object ProcessId,ParentProcessId,CreationDate,ExecutablePath,Name)
        foreach($descendant in $descendants) {
            try {
                $descendantProcess=[Diagnostics.Process]::GetProcessById($descendant.ProcessId)
                $descendant | Add-Member -NotePropertyName actualStartTicks -NotePropertyValue $descendantProcess.StartTime.ToUniversalTime().Ticks
                $descendantProcess.Dispose()
            } catch { $descendant | Add-Member -NotePropertyName actualStartTicks -NotePropertyValue $null }
        }
        $record.children=@($record.children)+$descendants
        if([DateTime]::UtcNow -ge $shaderDeadline) {$record.stopReason='Grant-wide 20-minute deadline'}
        elseif($free -lt 25GB) {$record.stopReason='D reserve early-stop threshold 25 GiB'}
        elseif($freeMemory -lt 8GB) {$record.stopReason='Free physical memory below 8 GiB'}
        elseif($bytes -ge 19GB) {$record.stopReason='Private growth early-stop threshold 19 GiB within 20 GiB envelope'}
        elseif((Get-FileHash -LiteralPath $shaderLeasePath).Hash.ToLowerInvariant() -ne $shaderLeaseHash) {$record.stopReason='Lease changed or revoked'}
        if($record.stopReason) {$child.Kill($true);$child.WaitForExit();break}
    }
} finally {
    if(-not $child.HasExited) {$record.stopReason='Supervisor exception';$child.Kill($true);$child.WaitForExit()}
    $record.exitCode=$child.ExitCode
    $record.finishedUtc=[DateTime]::UtcNow.ToString('o')
    $record.peakObservedPrivateLogicalBytes=$peak
    [IO.File]::WriteAllText((Join-Path $shaderEvidence 'worker.stdout.log'),$stdout.GetAwaiter().GetResult())
    [IO.File]::WriteAllText((Join-Path $shaderEvidence 'worker.stderr.log'),$stderr.GetAwaiter().GetResult())
    $child.Dispose()
    # Synchronously verify every observed child identity after root exit.
    foreach($owned in $record.children) {
        try {$live=[Diagnostics.Process]::GetProcessById($owned.ProcessId)} catch {continue}
        try {
            if($live.StartTime.ToUniversalTime().Ticks -eq $owned.actualStartTicks) {
                if(-not $live.HasExited) {$live.Kill($true);$live.WaitForExit()}
            }
        } finally {$live.Dispose()}
    }
    $record.allObservedChildrenExited=$true
    $record | ConvertTo-Json -Depth 7 | Set-Content (Join-Path $shaderEvidence 'process.json') -Encoding utf8
}
$installer=Join-Path $shaderDestination 'downloads\UnitySetup-Linux-IL2CPP-Support-for-Editor-6000.5.9f1.exe'
if((Test-Path -LiteralPath $installer) -and -not (Test-Path (Join-Path $shaderEvidence 'authenticode.json'))) {
    $signature=Get-AuthenticodeSignature -LiteralPath $installer
    [ordered]@{utc=[DateTime]::UtcNow.ToString('o');status=$signature.Status.ToString();statusMessage=$signature.StatusMessage;signerSubject=$signature.SignerCertificate.Subject;signerThumbprint=$signature.SignerCertificate.Thumbprint;timestampSubject=$signature.TimeStamperCertificate.Subject;signatureType=$signature.SignatureType.ToString();installerExecuted=$false} | ConvertTo-Json | Set-Content (Join-Path $shaderEvidence 'authenticode.json') -Encoding utf8
}
if($record.stopReason) {throw $record.stopReason}
if($record.exitCode -ne 0) {throw "File preparation worker exit $($record.exitCode); retain all evidence"}
$global:LASTEXITCODE=0
